def table(rows0,is_trans=False):
 for n,n1,n2,n3,typ,L,lam in rows0:
  if is_trans:flips=int(n1>n2)+int(n3>n2)
  else:flips=int(n2>n1)+int(n3>n2)
  half=((typ=='max')==(flips%2==1))
  note=f'Indices({n1},{n2},{n3}) give {flips} reflection phase reversals; '+('transmitted' if is_trans else 'reflected')+f' {typ} requires '+('half-integer' if half else 'integer')+' optical-path orders.'
  if isinstance(L,str):
   order=(1.5 if L=='2nd' else 2.5) if half else (1 if L=='2nd' else 2)
   val=order*lam*1e-9/(2*n2)
   R(n,[N('Required film thickness',val,'m',f'2n₂L={order}λ, using the requested {L} least positive half-integer thickness.')],note)
  else:
   delta=2*n2*L;vals=[]
   for m in range(1,30):
    order=m-.5 if half else m
    wave=delta/order
    if 400-1e-7<=wave<=700+1e-7:vals.append(wave)
   assert len(vals)==1,(n,vals)
   R(n,[N('Visible wavelength',vals[0]*1e-9,'m',f'2n₂L={delta:g}nm; select the sole wavelength in400–700nm from the '+('half-integer' if half else 'integer')+' order family.')],note)
